#!/usr/bin/env python3
"""Validate Python S-box model vs. Icarus ground truth."""
import subprocess, os, re

INIT = [
 0x85c4d834ef22d4b989d975ce78ebd3405fa9d7fe2f53040695f36fc62fdf2de9,
 0x4dae5f63ca800319a219922c878382b2042fa4cdccdb8c36e5f52f3e4b25edbf,
 0xb2e631e07d1eb7c2668faca8a8a281cf95319e83cb5e2b4e99443ba536189203,
 0xc7cdaaae5946de3c9caee12ea2628a47f915286c2baaa8db852721e3ff8aeae6,
 0xb38b73fc542cabf0e0042f00b1f984421a8f24fa3d7eca72027a937fa9a57071,
 0x75102ed9eed416f8b952d0bb2db7e5d16cdac02f5e90c3ca24b8126137044e48,
 0xb23dc192a95f0c6b677412424eb52e6cf301b96b267ef4eac6b49a342e317d8c,
 0x572d44ac3633a04b29c0dfb57023d812b6aa51fae993732dd138b4cb500eecc9,
] + [0]*8

# memory[w] = 16-bit word
memory = [0]*256
for n in range(16):
    for i in range(16):
        memory[n*16 + i] = (INIT[n] >> (16*i)) & 0xffff

def sbox_py(a):
    idx = a & 0x7f           # RADDR[7:0] with bit7 forced 0
    sel = (a >> 7) & 1       # RADDR[8]
    word = memory[idx]
    byte = 0
    for i in range(8):
        bit = (word >> (2*i + sel)) & 1
        byte |= bit << i
    return byte

S_py = [sbox_py(a) for a in range(256)]

# --- Icarus ground truth harness ---
inits = "\n".join(f'  .INIT_{d}(256\'h{INIT[i]:064x}),'
                  for i,d in enumerate("0123456789ABCDEF"))
# strip trailing comma on last
inits = inits.rsplit(',',1)[0]
hv = f'''
`timescale 1ns/1ps
module tb;
  reg clk=0; reg [10:0] raddr; wire [15:0] rdata;
  SB_RAM40_4K #(.READ_MODE(1),.WRITE_MODE(1),
{inits}
  ) u(.RDATA(rdata),.RCLK(clk),.RCLKE(1'b1),.RE(1'b1),.RADDR(raddr),
      .WCLK(1'b0),.WCLKE(1'b0),.WE(1'b0),.WADDR(11'b0),.MASK(16'b0),.WDATA(16'b0));
  integer a; reg [7:0] byt;
  initial begin
    for (a=0; a<256; a=a+1) begin
      raddr = {{2'b0, a[7], 1'b0, a[6:0]}};
      #1 clk=1; #1 clk=0; #1;
      byt = {{rdata[14],rdata[12],rdata[10],rdata[8],rdata[6],rdata[4],rdata[2],rdata[0]}};
      $display("%0d %0d", a, byt);
    end
    $finish;
  end
endmodule
'''
os.makedirs("sboxchk", exist_ok=True)
open("sboxchk/hv.v","w").write(hv)
cells = os.path.expanduser("~/apps/oss-cad-suite/share/yosys/ice40/cells_sim.v")
subprocess.run(["iverilog","-o","sboxchk/hv.vvp","-DNO_ICE40_DEFAULT_ASSIGNMENTS",
                "sboxchk/hv.v",cells],check=True)
out = subprocess.run(["vvp","sboxchk/hv.vvp"],capture_output=True,text=True).stdout
S_iv = [0]*256
for line in out.splitlines():
    line=line.strip()
    if re.match(r'^\d+ \d+$',line):
        a,v = map(int,line.split()); S_iv[a]=v

mism = [a for a in range(256) if S_py[a]!=S_iv[a]]
print("Icarus lines parsed:", sum(1 for l in out.splitlines() if re.match(r'^\d+ \d+$',l.strip())))
print("mismatches py-vs-icarus:", len(mism))
if mism[:5]:
    for a in mism[:5]: print(f"  a={a}: py={S_py[a]:02x} iv={S_iv[a]:02x}")
# bijection?
print("bijection:", len(set(S_py))==256)
print("S[0..15]:", " ".join(f"{S_py[a]:02x}" for a in range(16)))
print("is AES sbox[0]?", hex(S_py[0]), "(AES would be 0x63)")

